"""Responsive Flux Agent workspace dashboard."""

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#080b12">
<title>Flux — Agent workspace</title>
<style>
:root{color-scheme:dark;--bg:#080b12;--panel:#111a27;--line:#27364a;--text:#edf3fc;--muted:#8b9bb0;--cyan:#67e8f9;--violet:#a78bfa;--green:#a3e635;--red:#fb7185;--amber:#fbbf24;--shadow:0 18px 50px #0005}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 85% -20%,#273e6860,transparent 42%),radial-gradient(ellipse at 0 55%,#164e6330,transparent 35%),var(--bg);color:var(--text);font:14px/1.55 Inter,ui-sans-serif,system-ui,sans-serif;min-height:100vh}button,input,textarea,select{font:inherit}button{cursor:pointer}.hidden{display:none!important}
.shell{min-height:100vh;display:grid;grid-template-columns:238px minmax(0,1fr)}.sidebar{position:sticky;top:0;height:100vh;padding:25px 16px 18px;border-right:1px solid var(--line);background:#0b111bd9;display:flex;flex-direction:column;gap:28px;backdrop-filter:blur(18px)}.brand{display:flex;align-items:center;gap:11px;padding:0 9px}.logo{width:38px;height:38px;border-radius:13px;display:grid;place-items:center;color:#071018;font-size:21px;font-weight:950;background:linear-gradient(145deg,var(--cyan),#818cf8 58%,var(--violet));box-shadow:0 0 28px #67e8f933}.brand b{font-size:17px;letter-spacing:.02em}.brand small{display:block;color:var(--muted);font-size:9px;letter-spacing:.2em;text-transform:uppercase}.nav-label{padding:0 12px;margin-bottom:8px;color:#63738a;font-size:9px;font-weight:800;letter-spacing:.2em}.nav{display:grid;gap:5px}.nav button{width:100%;border:1px solid transparent;background:transparent;color:#aab7c9;text-align:left;padding:11px 12px;border-radius:11px;display:flex;align-items:center;gap:12px}.nav button:hover{background:#ffffff08;color:var(--text)}.nav button.active{color:white;border-color:#67e8f933;background:linear-gradient(100deg,#67e8f91b,#a78bfa12)}.nav-icon{width:20px;color:var(--cyan);font-size:16px;text-align:center}.side-bottom{margin-top:auto;border:1px solid var(--line);background:#101722;border-radius:14px;padding:13px}.side-bottom b{font-size:11px}.side-bottom p{margin:5px 0 0;color:var(--muted);font-size:10px}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:var(--green);box-shadow:0 0 10px #a3e63588;margin-right:7px}.main{width:100%;max-width:1600px;margin:0 auto;padding:30px clamp(17px,3.5vw,52px) 60px}.topbar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:26px}.eyebrow{color:var(--cyan);font-size:9px;letter-spacing:.2em;font-weight:850;text-transform:uppercase}.topbar h1{margin:4px 0 0;font-size:clamp(25px,3vw,34px);letter-spacing:-.05em}.top-right{display:flex;align-items:center;gap:10px}.api-pill{border:1px solid #a3e63536;background:#a3e6350c;color:var(--green);padding:7px 11px;border-radius:99px;font-size:10px}.avatar{width:36px;height:36px;border-radius:50%;display:grid;place-items:center;border:1px solid #a78bfa55;background:#a78bfa18;color:#d7ccff;font-weight:800}
.grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:15px}.card{min-width:0;background:linear-gradient(145deg,#141d2aee,#0f1621f2);border:1px solid var(--line);border-radius:17px;padding:19px;box-shadow:var(--shadow)}.hero{grid-column:span 8;min-height:205px;position:relative;overflow:hidden;padding:27px;background:linear-gradient(112deg,#1c2940,#182036 62%,#12303a)}.hero:after{content:"";position:absolute;width:280px;height:280px;border:1px solid #67e8f927;border-radius:50%;right:3%;top:-115px;box-shadow:0 0 0 25px #67e8f909,0 0 0 52px #67e8f906}.hero h2{position:relative;z-index:1;font-size:clamp(24px,3vw,34px);line-height:1.13;letter-spacing:-.05em;margin:10px 0}.hero p{position:relative;z-index:1;color:#b2c2d5;max-width:500px;margin:0 0 19px}.hero .btn{position:relative;z-index:1}.stat{grid-column:span 2;min-height:145px}.stat-label{color:var(--muted);font-size:10px;display:flex;justify-content:space-between}.stat-value{font-size:34px;font-weight:800;letter-spacing:-.06em;margin:15px 0 2px}.stat-note{font-size:10px;color:var(--muted)}.cyan{color:var(--cyan)}.green{color:var(--green)}.violet{color:var(--violet)}.red{color:var(--red)}
.section-title{grid-column:span 12;display:flex;justify-content:space-between;align-items:end;margin:13px 2px -2px}.section-title h2{font-size:15px;margin:0;letter-spacing:-.02em}.section-title p{font-size:10px;color:var(--muted);margin:3px 0 0}.composer{grid-column:span 7}.runs{grid-column:span 5}.card-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:14px}.card-head h3{font-size:13px;margin:0}.subtle{font-size:10px;color:var(--muted)}textarea{display:block;width:100%;min-height:125px;resize:vertical;padding:14px;border-radius:12px;border:1px solid #2c3a50;background:#0a111b;color:var(--text);outline:none;line-height:1.6}textarea:focus,input:focus,select:focus{border-color:#67e8f9;box-shadow:0 0 0 3px #67e8f91a;outline:none}.composer-foot{display:flex;align-items:center;gap:9px;margin-top:11px}.composer-foot select{background:#0a111b;border:1px solid var(--line);border-radius:10px;color:#d8e4f2;padding:10px}.composer-foot .btn{margin-left:auto}.btn{border:0;border-radius:10px;padding:10px 15px;color:#071018;font-weight:850;background:linear-gradient(100deg,#67e8f9,#a78bfa);box-shadow:0 8px 25px #67e8f91a}.btn:hover{filter:brightness(1.08);transform:translateY(-1px)}.btn:disabled{opacity:.55;cursor:wait;transform:none}.btn.ghost{background:#ffffff08;border:1px solid var(--line);color:#d9e4f2;box-shadow:none}.worker-note{margin-top:11px;padding:9px 11px;border:1px solid #fbbf2433;border-radius:10px;background:#fbbf2409;color:#d6bd83;font-size:10px}
.task-list{display:grid;gap:8px;max-height:390px;overflow:auto}.task-row{width:100%;display:flex;align-items:center;gap:10px;text-align:left;padding:10px;border:1px solid #263448;border-radius:12px;background:#0b121c;color:var(--text)}.task-row:hover,.task-row.selected{border-color:#67e8f966;background:#12202b}.task-icon{flex:0 0 32px;width:32px;height:32px;display:grid;place-items:center;border-radius:10px;background:#a78bfa19;color:var(--violet)}.task-copy{min-width:0;flex:1}.task-copy b{display:block;font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.task-copy small{display:block;color:var(--muted);font-size:9px;margin-top:2px}.tag{flex:0 0 auto;border-radius:99px;padding:4px 7px;background:#ffffff0c;color:#aab7c9;font-size:8px;text-transform:uppercase;letter-spacing:.08em}.tag.completed{background:#a3e63513;color:var(--green)}.tag.failed{background:#fb718513;color:var(--red)}.tag.running{background:#67e8f913;color:var(--cyan)}.empty{padding:26px 10px;text-align:center;color:var(--muted);font-size:11px}
.detail{grid-column:span 12}.detail-meta{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin:-4px 0 14px}.detail-prompt{padding:12px 14px;border:1px solid #263448;border-radius:11px;background:#0b121c;color:#c9d7e8;font-size:12px;white-space:pre-wrap;overflow-wrap:anywhere}.output-label{display:flex;align-items:center;justify-content:space-between;margin:17px 0 8px}.output-label b{font-size:11px}.output{margin:0;padding:16px;min-height:130px;max-height:480px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;border:1px solid #263448;border-radius:12px;background:#080e17;color:#dce9f7;font:12px/1.7 ui-monospace,SFMono-Regular,Consolas,monospace}.output.error{color:#fecdd3;border-color:#fb718544}.output.pending{color:var(--muted);font-family:inherit}.detail-actions{display:flex;gap:8px}.foot-grid{grid-column:span 12;display:grid;grid-template-columns:1fr 1fr;gap:15px}.mini{display:flex;justify-content:space-between;align-items:center;gap:15px}.mini b{font-size:12px}.mini small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.mini .glyph{font-size:22px;color:var(--violet)}
.login{max-width:440px;margin:12vh auto;padding:28px}.login h2{font-size:23px;letter-spacing:-.04em;margin:20px 0 5px}.login p{color:var(--muted);font-size:12px}.login input{width:100%;margin:14px 0;background:#0a111b;border:1px solid var(--line);border-radius:10px;padding:13px;color:var(--text)}.login .btn{width:100%}.toast{position:fixed;z-index:20;right:20px;bottom:20px;max-width:min(90vw,420px);padding:12px 15px;border:1px solid #42516a;border-radius:12px;background:#1b2635;box-shadow:var(--shadow);display:none;font-size:12px}
@media(max-width:1120px){.stat{grid-column:span 3}.hero{grid-column:span 12}.composer,.runs{grid-column:span 12}}
@media(max-width:700px){.shell{display:block}.sidebar{position:sticky;z-index:5;top:0;width:100%;height:auto;padding:10px 12px;border-right:0;border-bottom:1px solid var(--line);flex-direction:row;align-items:center;justify-content:space-between;gap:8px}.brand{padding:0}.logo{width:32px;height:32px}.nav-label,.side-bottom{display:none}.nav{display:flex;max-width:68vw;overflow:auto;gap:3px}.nav button{width:auto;padding:8px 10px;font-size:0;gap:0}.nav-icon{font-size:16px}.main{padding:20px 13px 40px}.topbar{margin-bottom:18px}.topbar h1{font-size:25px}.avatar{display:none}.grid{gap:10px}.card{padding:15px;border-radius:14px}.hero{min-height:190px;padding:21px}.stat{grid-column:span 6;min-height:120px}.stat-value{font-size:29px}.composer-foot{flex-wrap:wrap}.composer-foot select{flex:1}.composer-foot .btn{width:100%;margin:0}.foot-grid{grid-template-columns:1fr}.task-row{padding:9px}.detail-actions{width:100%}.detail-actions .btn{flex:1}}
</style>
</head>
<body>
<div id="login" class="card login">
 <div class="brand"><div class="logo">ϟ</div><div><b>flux</b><small>agent workspace</small></div></div>
 <h2>Connect your agent.</h2><p>Use the remote administrator token from your Flux host. It is kept in this browser tab session and is never displayed.</p>
 <form id="loginForm"><input id="tokenInput" type="password" autocomplete="current-password" placeholder="FLUX_REMOTE_TOKEN" required minlength="32"><button class="btn">Connect to Flux ↗</button></form>
 <p class="subtle">For network access, use HTTPS through a trusted private tunnel or reverse proxy.</p>
</div>
<div id="app" class="shell hidden">
 <aside class="sidebar">
  <div class="brand"><div class="logo">ϟ</div><div><b>flux</b><small>agent workspace</small></div></div>
  <div><div class="nav-label">WORKSPACE</div><nav class="nav">
   <button class="active" data-target="overview"><span class="nav-icon">◈</span>Overview</button><button data-target="agent"><span class="nav-icon">✳</span>Agent</button><button data-target="runs"><span class="nav-icon">▤</span>Runs</button><button data-target="settings"><span class="nav-icon">⚙</span>Settings</button>
  </nav></div>
  <div class="side-bottom"><b><span class="dot"></span>API connected</b><p>Authenticated session · local Flux host</p></div>
 </aside>
 <main class="main">
  <header class="topbar"><div><div class="eyebrow">FLUX / WORKSPACE</div><h1>Agent workspace</h1></div><div class="top-right"><span class="api-pill"><i class="dot"></i> API ONLINE</span><div class="avatar">F</div></div></header>
  <section id="overview" class="grid">
   <div class="card hero"><div class="eyebrow">YOUR LOCAL AI WORKSPACE</div><h2>Think. Build.<br><span class="cyan">Ship with Flux.</span></h2><p>Run conversations, create plans, and execute approved development tasks. Every run and its final response stays accessible here.</p><button class="btn" id="focusPrompt">＋ Start a new run</button></div>
   <div class="card stat"><div class="stat-label">TOTAL RUNS <span class="cyan">↗</span></div><div class="stat-value" id="total">—</div><div class="stat-note">Stored in your host queue</div></div>
   <div class="card stat"><div class="stat-label">COMPLETED <span class="green">✓</span></div><div class="stat-value" id="completed">—</div><div class="stat-note">Final output available</div></div>
   <div class="card stat"><div class="stat-label">ACTIVE <span class="violet">◌</span></div><div class="stat-value" id="active">—</div><div class="stat-note">Queued or running</div></div>
   <div class="card stat"><div class="stat-label">FAILED <span class="red">!</span></div><div class="stat-value" id="failed">—</div><div class="stat-note">Execution errors</div></div>
   <div class="section-title"><div><h2>Agent console</h2><p>Send an instruction to your Flux worker.</p></div><span class="subtle">CHAT · PLAN · BUILD</span></div>
   <div class="card composer" id="agent">
    <div class="card-head"><h3>New run</h3><span class="subtle">PROMPT</span></div><textarea id="prompt" maxlength="20000" placeholder="What should Flux work on?&#10;&#10;Example: Inspect my project, identify the highest-priority bugs, and propose fixes."></textarea>
    <div class="composer-foot"><select id="mode" aria-label="Execution mode"><option value="chat">Chat</option><option value="plan" selected>Plan</option><option value="build">Build</option></select><span class="subtle">Build actions request approval in the host terminal.</span><button class="btn" id="send">Run with Flux ↗</button></div>
    <div class="worker-note">Execution runs in a separate process. Keep <b>flux remote-worker</b> running in another Termux session to process queued tasks and return their output.</div>
   </div>
   <div class="card runs" id="runs"><div class="card-head"><h3>Run history</h3><button class="btn ghost" id="refresh" style="padding:7px 10px;font-size:10px">Refresh ↻</button></div><div id="tasklist" class="task-list"><div class="empty">Connect to your host to load runs.</div></div></div>
   <div class="card detail" id="outputPanel">
    <div class="card-head"><h3>Run details & output</h3><div class="detail-actions"><button class="btn ghost" id="copyOutput" disabled style="padding:7px 10px;font-size:10px">Copy output</button></div></div>
    <div id="detailMeta" class="detail-meta"><span class="subtle">Select a run from history to inspect its result.</span></div><div id="detailPrompt" class="detail-prompt hidden"></div>
    <div class="output-label"><b>FLUX RESPONSE</b><span id="outputHint" class="subtle">Final answer appears here</span></div><pre id="output" class="output pending">No run selected. Submit a prompt or choose an existing run to view its output.</pre>
   </div>
   <div class="foot-grid"><div class="card mini"><div><b>Workspace integrations</b><small>GitHub, messaging, browser and deployment adapters are configured on the Flux host.</small></div><span class="glyph">⌘</span></div><div class="card mini" id="settings"><div><b>Session & security</b><small>Your token stays in this tab session. Disconnect to clear it.</small></div><button class="btn ghost" id="logout">Disconnect</button></div></div>
  </section>
 </main>
</div>
<div id="toast" class="toast" role="status"></div>
<script>
(() => {
 let token=sessionStorage.getItem("flux.remote.token")||"",records=[],selectedId=null;
 const $=id=>document.getElementById(id),auth=()=>({Authorization:"Bearer "+token});
 function toast(message){$("toast").textContent=message;$("toast").style.display="block";clearTimeout(toast.timer);toast.timer=setTimeout(()=>$("toast").style.display="none",3600)}
 async function api(path,options={}){const response=await fetch(path,{...options,headers:{...auth(),...(options.headers||{})}});if(response.status===401){disconnect();throw new Error("Authentication failed. Check the remote token.")}const data=await response.json().catch(()=>({detail:"Unexpected server response"}));if(!response.ok)throw new Error(data.detail||"Request failed ("+response.status+")");return data}
 function showApp(){$("login").classList.add("hidden");$("app").classList.remove("hidden")}
 function disconnect(){token="";selectedId=null;sessionStorage.removeItem("flux.remote.token");$("app").classList.add("hidden");$("login").classList.remove("hidden");$("tokenInput").value=""}
 function dateLabel(value){if(!value)return"Time unavailable";const date=new Date(value);return Number.isNaN(date.getTime())?"Time unavailable":date.toLocaleString()}
 function statusTag(status){const tag=document.createElement("span");tag.className="tag "+(status||"");tag.textContent=status||"unknown";return tag}
 function render(){
  const counts={completed:0,failed:0,active:0};records.forEach(task=>{if(task.status==="completed")counts.completed++;else if(task.status==="failed")counts.failed++;else counts.active++});
  $("total").textContent=records.length;$("completed").textContent=counts.completed;$("active").textContent=counts.active;$("failed").textContent=counts.failed;
  const list=$("tasklist");list.replaceChildren();if(!records.length){const empty=document.createElement("div");empty.className="empty";empty.textContent="No runs yet. Start with a prompt in the Agent console.";list.append(empty);return}
  records.forEach(task=>{const row=document.createElement("button");row.type="button";row.className="task-row"+(task.id===selectedId?" selected":"");row.setAttribute("aria-label","Open run "+task.id);const icon=document.createElement("span");icon.className="task-icon";icon.textContent=task.mode==="build"?"⌘":task.mode==="plan"?"◎":"✳";const copy=document.createElement("span");copy.className="task-copy";const title=document.createElement("b");title.textContent=task.prompt||("Run #"+task.id);const meta=document.createElement("small");meta.textContent="#"+task.id+" · "+(task.mode||"chat")+" · "+dateLabel(task.created_at);copy.append(title,meta);row.append(icon,copy,statusTag(task.status));row.addEventListener("click",()=>selectTask(task.id));list.append(row)})
 }
 function showTask(task){
  selectedId=task.id;render();$("detailMeta").replaceChildren();const id=document.createElement("span");id.className="subtle";id.textContent="RUN #"+task.id;const mode=document.createElement("span");mode.className="subtle";mode.textContent=(task.mode||"chat").toUpperCase()+" MODE";const time=document.createElement("span");time.className="subtle";time.textContent=dateLabel(task.updated_at||task.created_at);$("detailMeta").append(id,document.createTextNode("·"),mode,document.createTextNode("·"),time,statusTag(task.status));$("detailPrompt").classList.remove("hidden");$("detailPrompt").textContent=task.prompt||"No prompt stored.";
  const output=$("output");output.className="output";
  if(task.status==="completed"&&task.result){output.textContent=task.result;$("outputHint").textContent="Completed · final response"}
  else if(task.status==="failed"){output.textContent=task.error||"The run failed without an error message.";output.classList.add("error");$("outputHint").textContent="Failed · execution error"}
  else if(task.status==="queued"){output.textContent="Waiting in the queue. Check that flux remote-worker is running on the host.";output.classList.add("pending");$("outputHint").textContent="Queued · waiting for worker"}
  else if(task.status==="running"){output.textContent="Flux is working on this run. This panel refreshes automatically when the response is ready.";output.classList.add("pending");$("outputHint").textContent="Running · waiting for final response"}
  else{output.textContent=task.result||task.error||"No output has been recorded yet.";$("outputHint").textContent="Run output"}
  $("copyOutput").disabled=!((task.result&&task.status==="completed")||(task.error&&task.status==="failed"))
 }
 async function selectTask(id){selectedId=id;try{const task=await api("/tasks/"+encodeURIComponent(id));showTask(task)}catch(error){toast(error.message)}}
 async function refresh(){try{const data=await api("/tasks");records=data.tasks||[];render();if(selectedId!==null){if(records.some(task=>task.id===selectedId))await selectTask(selectedId);else selectedId=null}else if(records.length)await selectTask(records[0].id)}catch(error){toast(error.message)}}
 $("loginForm").addEventListener("submit",async event=>{event.preventDefault();token=$("tokenInput").value.trim();try{await api("/health");await api("/tasks");sessionStorage.setItem("flux.remote.token",token);showApp();await refresh()}catch(error){toast(error.message)}});
 $("send").addEventListener("click",async()=>{const prompt=$("prompt").value.trim();if(!prompt){toast("Enter an instruction first.");$("prompt").focus();return}const button=$("send");button.disabled=true;button.textContent="Queueing…";try{const task=await api("/tasks",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({prompt,mode:$("mode").value})});$("prompt").value="";toast("Run #"+task.id+" added to the queue.");await refresh();await selectTask(task.id);$("outputPanel").scrollIntoView({behavior:"smooth",block:"nearest"})}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent="Run with Flux ↗"}});
 $("refresh").addEventListener("click",refresh);$("focusPrompt").addEventListener("click",()=>{$("prompt").focus();$("agent").scrollIntoView({behavior:"smooth",block:"center"})});$("logout").addEventListener("click",disconnect);
 $("copyOutput").addEventListener("click",async()=>{try{await navigator.clipboard.writeText($("output").textContent);toast("Output copied.")}catch(error){toast("Clipboard access is unavailable in this browser.")}});
 document.querySelectorAll(".nav button").forEach(button=>button.addEventListener("click",()=>{document.querySelectorAll(".nav button").forEach(item=>item.classList.remove("active"));button.classList.add("active");const target=$(button.dataset.target);if(target)target.scrollIntoView({behavior:"smooth",block:"start"})}));
 if(token){showApp();api("/health").then(refresh).catch(error=>toast(error.message))}setInterval(()=>{if(token)refresh()},4000);
})();
</script>
</body></html>"""
